solution.javascript:
function Twitter() {
  this.time = 0;
  this.tweets = new Map();
  this.following = new Map();
}
Twitter.prototype.postTweet = function(userId, tweetId) {
  if (!this.tweets.has(userId)) this.tweets.set(userId, []);
  this.tweets.get(userId).unshift({ id: tweetId, time: this.time++ });
};
Twitter.prototype.getNewsFeed = function(userId) {
  const ids = [userId, ...(this.following.get(userId) || [])];
  const pointers = ids.map(() => 0);
  const result = [];
  for (let i = 0; i < 10; i++) {
    let best = null, bestTime = -1, bestIdx = -1;
    for (let j = 0; j < ids.length; j++) {
      const list = this.tweets.get(ids[j]);
      if (!list || pointers[j] >= list.length) continue;
      const t = list[pointers[j]];
      if (t.time > bestTime) { bestTime = t.time; best = t.id; bestIdx = j; }
    }
    if (best === null) break;
    result.push(best); pointers[bestIdx]++;
  }
  return result;
};
Twitter.prototype.follow = function(followerId, followeeId) {
  if (followerId === followeeId) return;
  if (!this.following.has(followerId)) this.following.set(followerId, new Set());
  this.following.get(followerId).add(followeeId);
};
Twitter.prototype.unfollow = function(followerId, followeeId) {
  this.following.get(followerId)?.delete(followeeId);
};

solution.cpp:
class Twitter {
    int time = 0;
    unordered_map<int, vector<pair<int,int>>> tweets;
    unordered_map<int, unordered_set<int>> following;
public:
    void postTweet(int userId, int tweetId) {
        tweets[userId].emplace_back(time++, tweetId);
    }
    vector<int> getNewsFeed(int userId) {
        vector<int> ids = {userId};
        for (int id : following[userId]) ids.push_back(id);
        vector<int> ptr(ids.size());
        vector<int> result;
        for (int i = 0; i < 10; i++) {
            int best = -1, bestTime = -1, bestIdx = -1;
            for (int j = 0; j < ids.size(); j++) {
                auto& list = tweets[ids[j]];
                if (ptr[j] >= list.size()) continue;
                auto [t, id] = list[ptr[j]];
                if (t > bestTime) { bestTime = t; best = id; bestIdx = j; }
            }
            if (best == -1) break;
            result.push_back(best); ptr[bestIdx]++;
        }
        return result;
    }
    void follow(int followerId, int followeeId) {
        if (followerId != followeeId) following[followerId].insert(followeeId);
    }
    void unfollow(int followerId, int followeeId) {
        following[followerId].erase(followeeId);
    }
};
